3	import (
4		"errors"
5		"log"
6		"net/url"
7		"strconv"
8		"strings"
9	
10		tea "charm.land/bubbletea/v2"
11		"charm.land/lipgloss/v2"
12	
13		"github.com/anthnel/devdesk/internal/imagesearch"
14		"github.com/anthnel/devdesk/internal/jobs"
15		"github.com/anthnel/devdesk/internal/oci"
16		"github.com/anthnel/devdesk/internal/ui/datatable"
17		"github.com/anthnel/devdesk/internal/ui/indicator"
18		"github.com/anthnel/devdesk/internal/ui/shortcut"
19		"github.com/anthnel/devdesk/internal/ui/theme"
20	)
21	
22	// searchRow is one line of the level 1 table: an image, and the label of the
23	// registry that returned it.
24	type searchRow struct {
25		img   imagesearch.Image
26		label string
27		// ref is the full reference (host/repo), what the footer describes.
28		ref string
29	}
30	
31	// searchRowReference returns the full reference of an image found in the
32	// registry at registryURL: the host, then the final repository path. Docker
33	// Hub is always written docker.io, whichever spelling it is configured under.
34	func searchRowReference(registryURL string, img imagesearch.Image) string {
35		host := oci.RegistryHost(registryURL)
36		if host == "" {
37			return img.Repo
38		}
39		if oci.IsDockerHub(registryURL) {
40			host = "docker.io"
41		}
42		return host + "/" + img.Repo
43	}
44	
45	// searchColumns describes the level 1 table. Stars, Official and Description
46	// leave whole when the terminal narrows, in that reverse order (Description,
47	// Stars, Official), through Optional and DropFirst: drop() takes the rightmost
48	// DropFirst column first, then the rightmost Optional one.
49	func searchColumns() []datatable.Column[searchRow] {
50		return []datatable.Column[searchRow]{
51			datatable.IndicatorColumn(
52				func(searchRow) indicator.State { return indicator.Idle },
53				func(searchRow) string { return theme.IconDocker },
54				func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
55			),
56			{
57				Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
58				Cell:   func(r searchRow) string { return r.img.Name },
59				Search: func(r searchRow) string { return r.img.Name },
60			},
61			{
62				Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
63				Cell: func(r searchRow) string { return r.label },
64			},
65			{
66				Title: "Stars", Sizing: datatable.SizingFixed, Optional: true, DropFirst: true, MinWidth: 6,
67				Cell: func(r searchRow) string {
68					if !r.img.HasStars {
69						return ""
70					}
71					return strconv.Itoa(r.img.Stars)
72				},
73			},
74			{
75				Title: "Official", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10,
76				Cell: func(r searchRow) string {
77					if r.img.Official {
78						return "official"
79					}
80					return ""
81				},
82			},
83			{
84				Title: "Description", Sizing: datatable.SizingContent, Optional: true, DropFirst: true,
85				MinWidth: 20, Flex: 2,
86				Cell:   func(r searchRow) string { return r.img.Description },
87				Search: func(r searchRow) string { return r.img.Description },
88			},
89		}
90	}
91	
92	// newSearchTable builds the level 1 table; rebuildSearchTable orders its rows.
93	func newSearchTable() *datatable.Model[searchRow] {
94		t := datatable.New(datatable.Config[searchRow]{
95			Columns:    searchColumns(),
96			SortColumn: -1,
97		})
98		return &t
99	}
100	
101	// rebuildSearchTable hands the collected images to the table.
102	func (b *RegistryBrowser) rebuildSearchTable() {
103		rows := make([]searchRow, len(b.images))
104		for i, img := range b.images {
105			label, ref := "", img.Repo
106			if e := b.entryFor(img.EntryKey); e != nil {
107				label = b.entryLabel(img.EntryKey)
108				ref = searchRowReference(e.URL, img)
109			}
110			rows[i] = searchRow{img: img, label: label, ref: ref}
111		}
112		sortSearchRows(b.searchQuery, rows)
113		// The cursor follows the selected row by (EntryKey, Repo), not by index:
114		// rows of another registry land before or after it. Nothing selected (an
115		// empty table, so also a new search) goes to the first row, because an
116		// empty table keeps its old cursor index; a vanished row stays put.
117		prev, hadSel := b.searchTable.Selected()
118		b.searchTable.SetItems(rows)
119		if !hadSel {
120			b.searchTable.GotoTop()
121		} else {
122			for i, r := range b.searchTable.Visible() {
123				if r.img.EntryKey == prev.img.EntryKey && r.img.Repo == prev.img.Repo {
124					b.searchTable.SetCursor(i)
125					break
126				}
127			}
128		}
129		b.resizeTables()
130	}
131	
132	// AddImageResults takes one registry's answer. It returns false, touching
133	// nothing, when the answer belongs to another lot. pendingSearches never goes
134	// below zero.
135	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
136		if msg.Gen != b.gen {
137			return false
138		}
139		if b.pendingSearches > 0 {
140			b.pendingSearches--
141		}
142		oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
143		if b.outcomes == nil {
144			b.outcomes = map[string]imagesearch.Outcome{}
145		}
146		b.outcomes[msg.EntryKey] = oc
147		if oc.Verdict == imagesearch.VerdictOK {
148			for _, img := range msg.Images {
149				img.EntryKey = msg.EntryKey
150				b.images = append(b.images, img)
151			}
152		}
153		b.rebuildSearchTable()
154		return true
155	}
156	
157	// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
158	// back to the form; esc acts in order: the filter bar while it is open, then a
159	// confirmed query, then it cancels the lot and goes back to the form (which
160	// keeps the typed name and the selection). The lot's late answers are no
161	// longer wanted and are dropped
162	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
163	// nothing: a row has no action yet; → opens the row's tags.
164	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
165		if b.searchTable.InEditMode() {
166			return b, b.searchTable.Update(msg)
167		}
168		switch msg.String() {
169		case "right":
170			return b.openSelectedImageTags()
171		case "esc":
172			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
173				bar.ClearSearch()
174				b.searchTable.SetItems(b.searchTable.Items())
175				return b, nil
176			}
177			return b.backToForm()
178		case "left":
179			return b.backToForm()
180		case "enter":
181			return b, nil
182		}
183		return b, b.searchTable.Update(msg)
184	}
185	
186	// backToForm cancels the lot and returns to the form, which keeps the typed
187	// name and the selection. Late answers of the lot are dropped.
188	func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
189		b.abandonLot()
190		b.state = browserStateInput
191		b.searchTable.Blur()
192		b.updateFocus()
193		return b, nil
194	}
195	
196	// handleImageSearchResult records one registry's answer; a stale one is ignored.
197	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
198		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
199			return m, nil
200		}
201		oc, _ := m.registryBrowser.Outcome(msg.EntryKey)
202		alias := msg.EntryKey
203		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
204			alias = entryAlias(*e)
205		}
206		logSearchOutcome(alias, oc, msg.Err)
207		return m, nil
208	}
209	
210	// logSearchOutcome logs a registry's verdict: failed as an error, refused as
211	// info, nothing for ok or no result. The cause goes through searchErrorCause,
212	// so no secret or typed text reaches the log.
213	func logSearchOutcome(alias string, oc imagesearch.Outcome, err error) {
214		switch oc.Verdict {
215		case imagesearch.VerdictFailed:
216			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(err))
217		case imagesearch.VerdictRefused:
218			log.Printf("INFO [oci_resources] image search on %s: unsupported or refused: %s", alias, searchErrorCause(err))
219		}
220	}
221	
222	// searchErrorCause is the loggable text of a search error. A *url.Error holds
223	// the full request URL, which carries the text the user typed, so only its Op
224	// and Err are kept.
225	func searchErrorCause(err error) string {
226		var ue *url.Error
227		if errors.As(err, &ue) {
228			return jobs.SafeCause(errors.New(ue.Op + ": " + jobs.SafeCause(ue.Err)))
229		}
230		return jobs.SafeCause(err)
231	}
232	
233	// handleRegistryBrowserWarn shows the browser's warning in the footer.
234	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
235		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
236	}
237	
238	// tagsLoadFailedText is the footer text of a failed tag listing opened by →.
239	const tagsLoadFailedText = "Could not load tags"
240	
241	// selectedImage returns the level 1 row under the cursor with its registry
242	// entry; false when there is no row or the entry is no longer known.
243	func (b *RegistryBrowser) selectedImage() (searchRow, *browserRegistryEntry, bool) {
244		row, ok := b.searchTable.Selected()
245		if !ok {
246			return searchRow{}, nil, false
247		}
248		entry := b.entryFor(row.img.EntryKey)
249		return row, entry, entry != nil
250	}
251	
252	// imageDrillIn reports whether → has an image to open: a row under the cursor
253	// whose registry entry is still known. One computation for the header and the
254	// handler (Rule 130).
255	func (b *RegistryBrowser) imageDrillIn() shortcut.Availability {
256		if _, _, ok := b.selectedImage(); !ok {
257			return shortcut.Unavailable(reasonNoImage)
258		}
259		return shortcut.Availability{}
260	}
261	
262	// openSelectedImageTags lists the tags of the selected level 1 row, on that
263	// row's registry only, with the row's final repository as is (no prefix, no
264	// library/ added again). Without a row it changes nothing and warns. A level 1
265	// search still running is cancelled: the browser has one lot at a time.
266	func (b *RegistryBrowser) openSelectedImageTags() (*RegistryBrowser, tea.Cmd) {
267		if av := b.imageDrillIn(); !av.Enabled() {
268			reason := av.Reason
269			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: reason} }
270		}
271		row, entry, _ := b.selectedImage()
272		b, cmd := b.startTagRequests([]tagRequest{b.newTagRequest(*entry, row.img.Repo)}, true)
273		b.tagsImage = row.img.Name
274		return b, cmd
275	}
276	
277	// Outcome returns the verdict of entryKey in the current lot; false while
278	// pending.
279	func (b *RegistryBrowser) Outcome(entryKey string) (imagesearch.Outcome, bool) {
280		oc, ok := b.outcomes[entryKey]
281		return oc, ok
282	}
