3	import (
4		tea "charm.land/bubbletea/v2"
5	
6		"github.com/anthnel/devdesk/internal/config"
7		"github.com/anthnel/devdesk/internal/docker"
8		"github.com/anthnel/devdesk/internal/ui/keymap"
9	)
10	
11	// InEditMode returns true when a text input is active (blocks command mode).
12	func (b *RegistryBrowser) InEditMode() bool {
13		if b.state == browserStateInput && b.focusedField == brFieldRepo {
14			return true
15		}
16		if b.state == browserStateImages {
17			return b.searchTable.InEditMode()
18		}
19		return b.state == browserStateTags && b.filterActive
20	}
21	
22	// IsSearching returns true while registry tag queries are still in flight.
23	func (b *RegistryBrowser) IsSearching() bool {
24		return b.pendingSearches > 0
25	}
26	
27	// Update handles all messages for the browser.
28	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
29		switch msg := msg.(type) {
30		case tea.KeyPressMsg:
31			return b.handleKeyMsg(msg)
32		}
33		return b.delegateUpdate(msg)
34	}
