135	// requestDirectScan emits RegistryTagDirectScanMsg for a remote Trivy scan (no pull).
136	func (b *RegistryBrowser) requestDirectScan() (*RegistryBrowser, tea.Cmd) {
137		name := b.selectedImageName()
138		if name == "" {
139			return b, nil
140		}
141		return b, func() tea.Msg { return RegistryTagDirectScanMsg{ImageName: name} }
142	}
