144	// openTagScanDetails emits ScanDetailsRequestMsg when the selected tag has cached results.
145	func (b *RegistryBrowser) openTagScanDetails() (*RegistryBrowser, tea.Cmd) {
146		name := b.selectedImageName()
147		if name == "" {
148			return b, nil
149		}
150		if _, ok := b.scanCache[name]; !ok {
151			return b, nil
152		}
153		return b, func() tea.Msg { return ScanDetailsRequestMsg{ImageName: name} }
