156	// joinRepoPrefix puts an entry's prefix in front of the repository name.
157	//
158	// One slash, always: the prefix is a path segment and normalization has already
159	// refused one carrying a slash at either end, so there is nothing here to guess
160	// about (§3.18).
161	func joinRepoPrefix(prefix, repo string) string {
162		if prefix == "" {
163			return repo
164		}
165		return prefix + "/" + repo
166	}
167	
168	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
169	func normalizeRepoForRegistry(registryURL, repo string) string {
170		if strings.Contains(repo, "/") {
171			return repo
172		}
173		if oci.IsDockerHub(registryURL) {
174			return "library/" + repo
175		}
176		return repo
177	}
178	
179	// multiImageName constructs the full image reference for pull/scan.
180	//
181	// A Hub reference carries no host under docker: `docker pull nginx` leaves
182	// `nginx` as the local repository name, and qualifying it would only make the
183	// Images tab show `docker.io/library/nginx` next to a `nginx` pulled by hand.
184	// Podman disagrees, and not cosmetically — measured against a real podman
185	// with no `unqualified-search-registries` configured (§3.67), which is the
186	// package default on Debian/Ubuntu and Fedora alike: `podman pull
187	// library/nginx:tag` refuses outright ("short-name ... did not resolve to an
188	// alias and no unqualified-search registries are defined"), where docker
189	// would have silently assumed Hub. So the bare form is kept for docker, where
190	// it has always worked, and only podman gets the explicit host — which is
191	// also the form its own `images` list already uses (§3.67), so nothing about
192	// this makes a podman-pulled image look different from one already there.
193	func multiImageName(registryURL, repo, tag string) string {
194		if oci.IsDockerHub(registryURL) {
195			if engine.Current().Name == engine.Podman {
196				return "docker.io/" + repo + ":" + tag
197			}
198			return repo + ":" + tag
199		}
200		return oci.RegistryHost(registryURL) + "/" + repo + ":" + tag
201	}
202	
203	func (b *RegistryBrowser) updateFocus() {
204		b.repoInput.Blur()
205		if b.focusedField == brFieldRepo {
206			b.repoInput.Focus()
207		}
208	}
209	
210	// filteredMultiTags returns the tags the registry filter and the text filter let
211	// through. The order is the table's — it is what holds the cursor and the
212	// header arrow together.
213	func (b *RegistryBrowser) filteredMultiTags() []MultiRegistryTag {
214		query := strings.ToLower(b.filterInput.Value())
215		var result []MultiRegistryTag
216		for _, t := range b.tags {
217			if !b.registryFilter.matches(t.EntryKey, b.entryFor(t.EntryKey)) {
218				continue
219			}
220			if query != "" && !strings.Contains(strings.ToLower(t.Tag), query) &&
221				!strings.Contains(strings.ToLower(t.Repo), query) {
222				continue
223			}
224			result = append(result, t)
225		}
226		return result
227	}
