603		case "home":
604			m.table.GotoTop()
605			m.afterCursorMove()
606		case "end":
607			m.table.GotoBottom()
608			m.afterCursorMove()
609		}
610		return nil
611	}
612	
613	// ── Rows an action is running on ─────────────────────────────────────────────
614	//
615	// A row says two things at once: what the object *is*, and what is *happening*
616	// to it. They have different sources of truth — the state comes back from
617	// docker on the next refresh, the transition is this application's own
618	// knowledge — and different lifetimes. Sharing one glyph is the point; sharing
619	// one function would make every table re-implement the precedence, so the rule
620	// lives here and there is one of it: **busy wins over state**.
621	
622	// MarkBusy records that an action is running on the item with this key, and what
623	// to call it. Call it from Update, never from a Cmd (Rule 110).
624	//
625	// A no-op when the config declares no Key: without one there is nothing to
626	// match a row against, and silently keeping a label nothing can display would
627	// be worse than ignoring it.
628	func (m *Model[T]) MarkBusy(key, label string) {
629		if m.cfg.Key == nil || key == "" {
630			return
631		}
632		if m.busy == nil {
633			m.busy = make(map[string]string, 1)
634		}
635		m.busy[key] = label
636	}
637	
638	// ClearBusy forgets an action.
639	//
640	// It must be called on **every** outcome, the failures included. Clearing only
641	// on success leaves the row spinning for the life of the view, and — worse —
642	// hides the state it still has: a `docker stop` that failed has to read
643	// `running` again, not go on turning.
644	func (m *Model[T]) ClearBusy(key string) { delete(m.busy, key) }
645	
646	// IsBusy reports whether an action is running on this key.
647	//
648	// It answers for an object whose row does not exist yet, which is what makes it
649	// the guard on a confirm path: without it a second keypress on a slow removal
650	// issues a second command, and the second one fails with "no such object" on an
651	// operation that in fact worked.
652	func (m *Model[T]) IsBusy(key string) bool {
653		_, ok := m.busy[key]
654		return ok
655	}
656	
657	// BusyLabel returns the label of the action running on this key, if any.
658	func (m *Model[T]) BusyLabel(key string) (string, bool) {
659		label, ok := m.busy[key]
660		return label, ok
661	}
662	
663	// BusyLabels returns what is running, sorted, for a view's footer line. Sorted
664	// because a map's order changes between frames and a footer that reshuffles
665	// itself is unreadable.
666	func (m *Model[T]) BusyLabels() []string {
667		if len(m.busy) == 0 {
668			return nil
669		}
670		out := make([]string, 0, len(m.busy))
671		for _, label := range m.busy {
672			out = append(out, label)
673		}
674		sort.Strings(out)
675		return out
676	}
677	
678	// busyLabel returns the action running on an item, and whether there is one.
679	func (m *Model[T]) busyLabel(item T) (string, bool) {
680		if m.cfg.Key == nil || len(m.busy) == 0 {
681			return "", false
682		}
683		label, ok := m.busy[m.cfg.Key(item)]
684		return label, ok
685	}
686	
687	// SetTokenActive toggles one of the bar's filter tokens and re-applies it.
688	func (m *Model[T]) SetTokenActive(label string, active bool) {
689		m.bar.SetTokenActive(label, active)
690		m.rebuild()
691		m.Remeasure() // a toggle is a user action on a settled population
692	}
693	
694	// IsTokenActive reports whether a toggle filter is on.
695	func (m *Model[T]) IsTokenActive(label string) bool { return m.bar.IsTokenActive(label) }
696	
697	// rebuild filters, sorts, writes the rows and puts the cursor somewhere real.
698	func (m *Model[T]) rebuild() {
699		m.visible = m.sorted(m.filtered())
700	
701		// The natural widths are taken here because the cells are already being
702		// built: the measurement is a lipgloss.Width per cell on a walk that
703		// happens anyway. Promoting them to the solver is a separate decision
704		// (see Remeasure) — this only keeps the answer current.
705		//
706		// The header counts. A content column narrower than its own title truncates
707		// the one cell that says what the column is, and "the width the content
708		// wants" plainly includes being able to name itself.
709		m.natural = make([]int, len(m.cfg.Columns))
710		for j, c := range m.cfg.Columns {
711			m.natural[j] = lipgloss.Width(c.Title)
712		}
713	
714		rows := make([]table.Row, len(m.visible))
715		for i, item := range m.visible {
716			cells := make(table.Row, len(m.cfg.Columns))
717			for j, c := range m.cfg.Columns {
718				cells[j] = c.Cell(item)
719				if w := lipgloss.Width(cells[j]); w > m.natural[j] {
720					m.natural[j] = w
721				}
722			}
723			rows[i] = cells
724		}
725		m.table.SetRows(rows)
726	
727		// bubbles/table leaves the cursor where it was, so a list that just got
728		// shorter strands it past the end until the user presses a key. It also
729		// reports -1 while there are no rows at all, and that has to be taken back
730		// when rows return — a filter typed past its last match and then corrected
731		// would otherwise leave the table showing rows none of which is selected.
732		switch cursor := m.table.Cursor(); {
733		case len(rows) == 0:
734			// -1 is bubbles' own "nothing selected", and what it reports for a
735			// table that never had rows. Leaving the old index would make an empty
736			// list the one state where the cursor points past the end.
737			m.table.SetCursor(-1)
738		case cursor >= len(rows):
739			m.table.SetCursor(len(rows) - 1)
740		case cursor < 0:
741			m.table.SetCursor(0)
742		}
743		m.afterCursorMove()
744	}
745	
746	// afterCursorMove is what every cursor, height and item change ends with: the
747	// styles follow the selected item, and the scroll window follows the cursor.
748	// Keeping them on one call is what stops a new call site from remembering one
749	// and forgetting the other — the offset was invisible while bubbles owned it.
750	func (m *Model[T]) afterCursorMove() {
751		m.clampOffset()
752		m.applyStyles()
753	}
754	
755	// applyStyles asks the view for the styles that go with the selected item.
756	func (m *Model[T]) applyStyles() {
757		if !m.table.Focused() {
758			return // Blur owns the styles until Focus takes them back
759		}
760		styles := theme.DefaultTableStyles()
761		if item, ok := m.Selected(); ok {
762			if m.cfg.SelectedStyles != nil {
763				styles = m.cfg.SelectedStyles(item)
764			}
765			// Busy wins over whatever the view asked for, and this is the one place
766			// it can be said: the highlight is applied to the joined row, so a
767			// colour inside it would close with a reset and end the highlight
768			// mid-row (see render.go). An `exited` container being removed is not
769			// exited-and-that-is-that — the state is what the action is about to
770			// change, so the transition is the newer fact.
771			if _, busy := m.busyLabel(item); busy {
772				styles.Selected = theme.TableStylesForState("busy").Selected
773			}
774		}
775		// The background is the signal: only the plain "normal" look carries
776		// ColorTableLineSelected, so this is true exactly when no view-level state or
777		// busy override took over the row — see cellStyle for what it changes.
778		m.preserveColumnColors = styles.Selected.GetBackground() == theme.ColorTableLineSelected
779		m.setStyles(styles)
780	}
781	
782	// setStyles keeps bubbles' copy and this package's in step. The rendering reads
783	// the one here (render.go); bubbles' is still what Table() reports, which the
784	// tests and any view reaching for the raw table expect to be current.
785	func (m *Model[T]) setStyles(styles table.Styles) {
786		m.styles = styles
787		m.table.SetStyles(styles)
788	}
789	
790	// filtered applies the search query and the toggle filters.
791	func (m *Model[T]) filtered() []T {
792		query := strings.ToLower(strings.TrimSpace(m.bar.SearchQuery()))
793		active := m.activeTokens()
794	
795		out := make([]T, 0, len(m.items))
796		for _, item := range m.items {
797			if m.cfg.TokenMatch != nil && !m.cfg.TokenMatch(item, active) {
798				continue
799			}
800			if query != "" && !m.matchesQuery(item, query) {
801				continue
802			}
803			out = append(out, item)
804		}
805		return out
806	}
807	
808	func (m *Model[T]) activeTokens() map[string]bool {
809		active := make(map[string]bool, len(m.cfg.Tokens))
810		for _, tok := range m.cfg.Tokens {
811			if m.bar.IsTokenActive(tok.Label) {
812				active[tok.Label] = true
813			}
814		}
815		return active
816	}
817	
818	// matchesQuery tests the query against each searchable column and then against
819	// the row as a whole.
820	//
821	// The row-level pass is what keeps a query spanning two fields — "tcp 22" over a
822	// ports list — working: netdiag matched against a joined haystack while the
823	// other four filter loops matched per field, and per field alone would have
824	// quietly dropped those matches on migration. Matching both ways is a superset
825	// of either, so no view loses anything and they all gain the same thing.
826	func (m *Model[T]) matchesQuery(item T, query string) bool {
827		var joined strings.Builder
828		for _, c := range m.cfg.Columns {
829			if c.Search == nil {
830				continue
831			}
832			value := c.Search(item)
833			if strings.Contains(strings.ToLower(value), query) {
834				return true
835			}
836			if joined.Len() > 0 {
837				joined.WriteByte(' ')
838			}
839			joined.WriteString(value)
840		}
841		return strings.Contains(strings.ToLower(joined.String()), query)
842	}
843	
844	// sorted orders the visible slice. SliceStable, because sort.Slice is not and
845	// two rows equal on the sort column would otherwise swap between rebuilds.
846	func (m *Model[T]) sorted(items []T) []T {
847		if m.sortColumn < 0 {
848			return items
849		}
850		less := m.cfg.Columns[m.sortColumn].Less // never nil — see New
851		desc := m.sortDesc
852		sort.SliceStable(items, func(i, j int) bool {
853			if desc {
854				return less(items[j], items[i])
855			}
856			return less(items[i], items[j])
857		})
858		return items
859	}
860	
861	// Span is one coloured run of a multi-run cell (Column.Spans): Width cells of
862	// the cell's already-fitted text, painted with Style. Style must not carry
863	// Width, Padding or Margin: they would change the cell's width (as for Cut).
864	type Span struct {
865		Width int
866		Style lipgloss.Style
867	}
868	
869	// IndicatorColumn builds the activity column (Rule 125 shape: untitled, fixed,
870	// IconColumnWidth). It is the only way a view builds one. Only the first column
871	// carrying an Indicator is honoured (Model.indicatorAt); later ones are ignored.
872	func IndicatorColumn[T any](state func(T) indicator.State,
873		rest func(T) string, restStyle func(T) lipgloss.Style) Column[T] {
874		c := Column[T]{
875			Sizing: SizingFixed, MinWidth: IconColumnWidth,
876			Indicator: state,
877			Cell: func(item T) string {
878				if rest == nil {
879					return ""
880				}
881				return rest(item)
882			},
883		}
884		if restStyle != nil {
885			c.Style = restStyle
886		}
887		return c
888	}
889	
890	// SetBlinkPhase sets the phase read at render. Read at render; nothing is rebuilt.
891	func (m *Model[T]) SetBlinkPhase(on bool) { m.blinkOn = on }
892	
893	// BlinkPhase reports the current blink phase.
894	func (m *Model[T]) BlinkPhase() bool { return m.blinkOn }
