135				fb.tokens[i].Active = active
136				return
137			}
138		}
139	}
140	
141	// SetTokens replaces the token list. Active state is preserved for tokens
142	// whose label matches an existing active token.
143	func (fb *FilterBar) SetTokens(tokens []FilterToken) {
144		activeLabels := make(map[string]bool)
145		for _, t := range fb.tokens {
146			if t.Active {
147				activeLabels[t.Label] = true
148			}
149		}
150		fb.tokens = make([]FilterToken, len(tokens))
151		copy(fb.tokens, tokens)
152		for i, t := range fb.tokens {
153			if activeLabels[t.Label] {
154				fb.tokens[i].Active = true
155			}
156		}
157	}
158	
159	// Update handles key messages when the bar is in search mode.
160	// It returns the updated FilterBar and a Bubble Tea command.
161	// Call this from the view's Update() when fb.InEditMode() is true.
162	func (fb *FilterBar) Update(msg tea.Msg) (FilterBar, tea.Cmd) {
163		if !fb.searching {
164			return *fb, nil
165		}
166		if paste, ok := msg.(tea.PasteMsg); ok {
167			// A paste is text for the search input, never an action key. The
168			// input turns newlines into spaces itself.
169			var cmd tea.Cmd
170			fb.searchInput, cmd = fb.searchInput.Update(paste)
171			fb.searchQuery = fb.searchInput.Value()
172			return *fb, cmd
173		}
174		keyMsg, ok := msg.(tea.KeyPressMsg)
175		if !ok {
176			return *fb, nil
177		}
178		switch keyMsg.String() {
179		case "esc":
180			fb.searching = false
181			fb.searchQuery = ""
182			fb.searchInput.SetValue("")
183			fb.searchInput.Blur()
184			return *fb, nil
185		case "enter":
186			fb.searching = false
187			fb.searchQuery = fb.searchInput.Value()
188			fb.searchInput.Blur()
189			return *fb, nil
190		}
191		var cmd tea.Cmd
192		fb.searchInput, cmd = fb.searchInput.Update(msg)
193		fb.searchQuery = fb.searchInput.Value()
194		return *fb, cmd
195	}
196	
197	// View renders the filter bar as two lines forming a closed rectangle.
198	// The viewport's bottom border (└──────┘) serves as the top of the rectangle.
199	//
200	// Line 1 (content): │  / cursor...   [tcp] · [LISTEN]  │
201	// Line 2 (bottom):  └──────────────────────────────────┘
202	func (fb *FilterBar) View() string {
203		var right string
204		if len(fb.tokens) > 0 {
205			var activeTokens []string
206			for _, t := range fb.tokens {
207				if t.Active {
208					activeTokens = append(activeTokens, theme.KeyStyle.Render(t.Label))
209				}
210			}
211			if len(activeTokens) > 0 {
212				right = "  " + strings.Join(activeTokens, theme.DimStyle.Render("  ·  "))
213			}
214		}
215	
216		var left string
217		if fb.searching {
218			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + fb.searchInput.View()
219		} else {
220			if fb.searchQuery != "" {
221				left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(fb.searchQuery)
222			} else {
223				left = theme.DimStyle.Render("/ search...")
224			}
225		}
226	
227		return BarFrame(fb.width, theme.Bg(" ")+left+theme.Bg(right))
228	}
