75	// cachedNoResultMark follows a name in the Cached only line when that registry
76	// answered with no result: with a cache-only list, it means nothing is cached.
77	const cachedNoResultMark = " (no result)"
78	
79	// summarizeSearch sorts the lot's keys into classes. Pure; names are label(key),
80	// in the order of keys. cachedOnly says which keys list cached content only; a
81	// concerned key that answered ok or with no result goes to CachedOnly (the
82	// no-result one marked, and not in NoResult), a partial one also to Partial.
83	func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
84		label func(key string) string, cachedOnly func(key string) bool) searchSummary {
85		var s searchSummary
86		for _, k := range keys {
87			oc, ok := outcomes[k]
88			if !ok {
89				if live {
90					s.Pending++
91				} else {
92					s.Interrupted = append(s.Interrupted, label(k))
93				}
94				continue
95			}
96			switch oc.Verdict {
97			case imagesearch.VerdictFailed:
98				s.Failed = append(s.Failed, label(k))
99			case imagesearch.VerdictRefused:
100				s.Refused = append(s.Refused, label(k))
101			case imagesearch.VerdictNoResult:
102				if oc.Skipped {
103					s.Skipped = append(s.Skipped, label(k))
104					continue
105				}
106				if oc.Partial {
107					s.Partial = append(s.Partial, label(k))
108				}
109				if cachedOnly(k) {
110					s.CachedOnly = append(s.CachedOnly, label(k)+cachedNoResultMark)
111					continue
112				}
113				s.NoResult = append(s.NoResult, label(k))
114			case imagesearch.VerdictOK:
115				if oc.Partial {
116					s.Partial = append(s.Partial, label(k))
117				}
118				if cachedOnly(k) {
119					s.CachedOnly = append(s.CachedOnly, label(k))
120				}
121			}
122		}
123		return s
124	}
125	
126	// searchSummary summarizes the current level 1 lot (live: b.gen == b.searchGen).
127	func (b *RegistryBrowser) searchSummary() searchSummary {
128		return summarizeSearch(b.searchKeys, b.outcomes, b.gen == b.searchGen, b.entryLabel, b.entryCachedOnly)
129	}
130	
131	// entryCachedOnly reports whether the entry behind key lists cached content only.
132	func (b *RegistryBrowser) entryCachedOnly(key string) bool {
133		e := b.entryFor(key)
134		return e != nil && e.cachedOnly
135	}
136	
137	// entryLabel is the Registry column's label for key: entryAlias, else the URL,
138	// else the key itself.
139	func (b *RegistryBrowser) entryLabel(key string) string {
140		e := b.entryFor(key)
141		if e == nil {
142			return key
143		}
144		if a := entryAlias(*e); a != "" {
145			return a
146		}
147		if e.URL != "" {
148			return e.URL
149		}
150		return key
151	}
152	
153	// searchHeaderInfo is the level 1 header: the image count, then one line per class
154	// that has something to say (nothing when every registry answered: only the count).
155	// Order: Pending or Interrupted, Failed (red), Refused, Partial (orange), Cached only (orange), No result,
156	// Skipped (grey). Each name list is abbreviated by fitNames to the room the header
157	// gives a value, so a +N is never lost; Skipped drops its hint first. termWidth 0
158	// or less means the width is not known yet. At most shortcut.HeaderRows lines.
159	func searchHeaderInfo(images int, s searchSummary, termWidth int) []shortcut.HeaderInfo {
160		type line struct {
161			key    string
162			names  []string
163			count  string // a ready value, instead of names
164			suffix string
165			style  lipgloss.Style
166		}
167		warn := theme.HeaderWarnValueStyle()
168		var lines []line
169		if s.Pending > 0 {
170			lines = append(lines, line{key: "Pending", count: fmt.Sprintf("%d", s.Pending), style: theme.HeaderValueStyle})
171		}
172		lines = append(lines,
173			line{key: "Interrupted", names: s.Interrupted, style: warn},
174			line{key: "Failed", names: s.Failed, style: theme.SeverityTextStyle("CRITICAL")},
175			line{key: "Refused", names: s.Refused, style: warn},
176			line{key: "Partial", names: s.Partial, style: warn},
177			line{key: "Cached only", names: s.CachedOnly, style: warn},
178			line{key: "No result", names: s.NoResult, style: theme.DimStyle},
179			line{key: "Skipped", names: s.Skipped, suffix: skippedHint, style: theme.DimStyle},
180		)
181		var kept []line
182		keys := []string{"Images"}
183		for _, l := range lines {
184			if l.count == "" && len(l.names) == 0 {
185				continue
186			}
187			// The budget is HeaderRows lines: Images plus six classes. Pending and
188			// Interrupted exclude each other, which leaves seven classes, and
189			// Skipped (last) is the one cut if all the others are present at once.
190			// That cannot happen today: Skipped only comes from CatalogSearcher
191			// (ErrQueryTooShort), and with defaultImageSearcher = ByRegistry(Hub,
192			// Catalog) every non-Hub entry goes through it. So when Skipped is
193			// present every Nexus entry is Skipped and Cached only is empty: the
194			// two exclude each other, at most seven lines. A dedicated Nexus
195			// searcher would break that assumption. A new line (IS-14) must
196			// revisit this bound rather than be cut silently.
197			if len(kept)+1 >= shortcut.HeaderRows {
198				break
199			}
200			kept = append(kept, l)
201			keys = append(keys, l.key)
202		}
203		room := noWidthLimit
204		if termWidth > 0 {
205			room = shortcut.HeaderValueWidth(termWidth, keys)
206		}
207		infos := []shortcut.HeaderInfo{{Key: "Images", Value: fmt.Sprintf("%d", images), Style: theme.HeaderValueStyle}}
208		for _, l := range kept {
209			v := l.count
210			if v == "" {
211				v = fitNames(l.names, l.suffix, room)
212			}
213			infos = append(infos, shortcut.HeaderInfo{Key: l.key, Value: v, Style: l.style})
214		}
215		return infos
216	}
