1	package ociresources
2	
3	import (
4		"slices"
5		"strings"
6		"testing"
7	
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/imagesearch"
11		"github.com/anthnel/devdesk/internal/jobs"
12		"github.com/anthnel/devdesk/internal/ui/help"
13		"github.com/anthnel/devdesk/internal/ui/indicator"
14		"github.com/anthnel/devdesk/internal/ui/shortcut"
15		"github.com/anthnel/devdesk/internal/ui/testutil"
16	)
17	
18	// Level 1 of the image search on screen (DEVDESK-395, IS-01 c.7 and c.8): the
19	// header count, the shortcuts, the help, the filter bar, esc, the loading
20	// state in the footer (Rules 114, 125, 128, 130, 139) and enter doing nothing.
21	
22	// searchingModel opens the browser at level 1 with both registries still
23	// pending: the lot is started, no answer has come back yet.
24	func lvl1SearchingModel(t *testing.T) Model {
25		t.Helper()
26		withImageSearcher(t, &fakeSearcher{})
27		m, cmd := submitRaw(t, browsingModel(t), "nginx")
28		if cmd == nil {
29			t.Fatal("the search started nothing")
30		}
31		if m.registryBrowser.state != browserStateImages {
32			t.Fatalf("state = %d, want browserStateImages", m.registryBrowser.state)
33		}
34		if m.registryBrowser.pendingSearches != 2 {
35			t.Fatalf("pendingSearches = %d, want 2", m.registryBrowser.pendingSearches)
36		}
37		return m
38	}
39	
40	// answer feeds one registry's answer, stamped with the open lot.
41	func lvl1Answer(t *testing.T, m Model, entryKey string, names ...string) Model {
42		t.Helper()
43		images := make([]imagesearch.Image, len(names))
44		for i, n := range names {
45			images[i] = imagesearch.Image{EntryKey: entryKey, Name: n, Repo: n}
46		}
47		return feed(t, m, ImageSearchResultMsg{Gen: m.registryBrowser.gen, EntryKey: entryKey, Images: images})
48	}
49	
50	// imagesModel is level 1 settled with three rows: two from "prod", one from "hub".
51	func lvl1ImagesModel(t *testing.T) Model {
52		t.Helper()
53		m := lvl1SearchingModel(t)
54		m = lvl1Answer(t, m, "prod", "nginx", "nginx-unprivileged")
55		m = lvl1Answer(t, m, "hub", "redis")
56		if got := len(m.registryBrowser.searchTable.Visible()); got != 3 {
57			t.Fatalf("fixture holds %d rows, want 3", got)
58		}
59		if m.registryBrowser.pendingSearches != 0 {
60			t.Fatalf("pendingSearches = %d, want 0", m.registryBrowser.pendingSearches)
61		}
62		return m
63	}
64	
65	func lvl1Header(t *testing.T, m Model, key string) string {
66		t.Helper()
67		for _, info := range m.GetHeaderInfo("") {
68			if info.Key == key {
69				return info.Value
70			}
71		}
72		return ""
73	}
74	
75	func lvl1Names(m Model) []string {
76		var out []string
77		for _, r := range m.registryBrowser.searchTable.Visible() {
78			out = append(out, r.img.Name)
79		}
80		return out
81	}
82	
83	func lvl1Footer(m Model) string {
84		return ansi.Strip(m.RenderFooter(120))
85	}
86	
87	// c.7: the header counts the visible rows.
88	func TestLevelOneHeaderCountsTheVisibleImages(t *testing.T) {
89		m := lvl1SearchingModel(t)
90		if got := lvl1Header(t, m, "Images"); got != "0" {
91			t.Errorf("Images before any answer = %q, want 0", got)
92		}
93		m = lvl1ImagesModel(t)
94		if got := lvl1Header(t, m, "Images"); got != "3" {
95			t.Errorf("Images after the answers = %q, want 3", got)
96		}
97		if got := lvl1Header(t, m, "Disk Usage"); got != "" {
98			t.Errorf("the local Images tab's Disk Usage leaked into level 1: %q", got)
99		}
100	
101		m = feed(t, m, testutil.Key("/"))
102		m = feed(t, m, testutil.Type("redis")...)
103		m = feed(t, m, testutil.Key("enter"))
104		if got := lvl1Header(t, m, "Images"); got != "1" {
105			t.Errorf("Images after a filter = %q, want 1", got)
106		}
107	}
108	
109	// c.7: the filter bar of level 1 filters on the name.
110	func TestLevelOneFilterBarFiltersOnTheName(t *testing.T) {
111		m := lvl1ImagesModel(t)
112		m = feed(t, m, testutil.Key("/"))
113		if !m.registryBrowser.searchTable.InEditMode() {
114			t.Fatal("/ did not open the filter bar")
115		}
116		if !m.registryBrowser.FilterIsVisible() {
117			t.Error("the filter bar is not visible after /")
118		}
119		if got, want := m.GetFooterHeight(), 4; got != want {
120			t.Errorf("GetFooterHeight with the bar = %d, want %d", got, want)
